+static void usage(int, char ** argv) {
+    std::fprintf(stderr, "Usage: %s --trace-out PATH -m MODEL [-p PROMPT | -f FILE] -n N [-ngl N] [-c N]\n"
+                         "Greedy; exactly N generated tokens are evaluated, including EOG. Default N=32.\n", argv[0]);
