+    common_init();
+    common_params params;
+    params.n_predict = 32;
+    std::vector<char *> args = { argv[0] };
+    std::string trace_path;
+    for (int i = 1; i < argc; ++i) {
+        if (std::strcmp(argv[i], "--trace-out") == 0) {
+            if (++i >= argc || !trace_path.empty()) {
+                usage(argc, argv);
+                return 1;
+            }
+            trace_path = argv[i];
+        } else {
