 45	
 46	    std::vector<float>   crf;      // [n_layer*n_expert]
 47	    std::vector<int64_t> last_use; // [n_layer*n_expert] layer clock at the last use, -1 if not used
 48	    std::vector<int64_t> clock;    // [n_layer] tokens seen by the layer (as added by plan() for each ubatch)
 49	
 50	    std::vector<uint32_t> seen; // [n_expert] seen[e] == seen_gen if expert e is selected by the current plan()
 51	    uint32_t seen_gen = 0;
 52	    std::vector<int32_t> uniq;  // the distinct selected experts
 53	    std::vector<int32_t> misses;
 54	    std::vector<uint64_t> token_zero; // [n_tokens] zero slots used by each token
 55	
 56	    void init(int32_t n_layer, int32_t n_expert, int32_t n_slots) {
 57	        GGML_ASSERT(n_class == (int) std::log2(1.0f/(1.0f - std::exp2(-1.0f/crf_half_life))) + 1);
 58	        this->n_expert = n_expert;
 59	        this->n_slots  = n_slots;
 60	        this->empty    = n_slots;
 61	        slot_map.assign(n_layer, nullptr);
 62	        key_of.assign(n_slots, -1);
 63	        prev.resize(n_slots);
 64	        next.resize(n_slots);
 65	        for (int32_t s = 0; s < n_slots; ++s) {
 66	            prev[s] = s - 1;
 67	            next[s] = s + 1 < n_slots ? s + 1 : -1;
 68	        }
 69	        for (int c = 0; c < n_class; ++c) {
 70	            head[c] = -1;
 71	            tail[c] = -1;
 72	        }
 73	        head[0] = 0;
 74	        tail[0] = n_slots - 1;
 75	        list_of.assign(n_slots, 0);
 76	        crf.assign((size_t) n_layer*n_expert, 0.0f);
 77	        last_use.assign((size_t) n_layer*n_expert, -1);
 78	        clock.assign(n_layer, 0);
 79	        seen.assign(n_expert, 0);
 80	    }
 81	
 82	    // move slot s to the most recently used end of list c
 83	    void move(int32_t s, int c) {
 84	        const int from = list_of[s];
 85	        if (from == c && s == tail[from]) {
 86	            return;
 87	        }
 88	        if (prev[s] >= 0) {
 89	            next[prev[s]] = next[s];
 90	        } else {
 91	            head[from] = next[s];
 92	        }
 93	        if (next[s] >= 0) {
 94	            prev[next[s]] = prev[s];
 95	        } else {
 96	            tail[from] = prev[s];
 97	        }
 98	
 99	        prev[s] = tail[c];
100	        next[s] = -1;
101	        if (tail[c] >= 0) {
102	            next[tail[c]] = s;
103	        } else {
104	            head[c] = s;
105	        }
106	        tail[c] = s;
107	        list_of[s] = c;
108	    }
109	
110	    // key = index of an expert of a layer in crf and last_use
111	    int32_t make_key(int32_t il, int32_t e) const { return il*n_expert + e; }
112	    int32_t key_layer (int32_t key) const { return key / n_expert; }
113	    int32_t key_expert(int32_t key) const { return key % n_expert; }
114	
115	    // for a key after use(): its CRF is >= 1, so log2 is >= 0 and the cast is the floor
116	    int class_of(int32_t key) const {
117	        return std::min(n_class - 1, (int) std::log2(crf[key]));
118	    }
119	
120	    // the CRF of a key, decayed by the time since its last use
121	    float decayed_crf(int32_t il, int32_t key) const {
122	        return crf[key]*std::exp2(-(clock[il] - last_use[key])/crf_half_life);
123	    }
124	
125	    // an unused key gets 1 because crf[key] is 0 prior to first use
126	    void use(int32_t il, int32_t key) {
127	        crf[key]      = decayed_crf(il, key) + 1.0f;
128	        last_use[key] = clock[il];
129	    }
130	
131	    // the experts selected by this plan() must not be evicted, nor the slots this plan() filled already
132	    bool is_selected(int32_t il, int32_t key) const {
133	        if (key < 0) {
134	            return false; // unused slot
135	        }
136	        if (key_layer(key) != il) {
137	            return false; // seen is per expert index, an expert of another layer can have the same index
138	        }
139	        return seen[key_expert(key)] == seen_gen;
140	    }
141	
142	    // the least recently used slot of list c that this plan() does not select, -1 if none
143	    int32_t candidate(int c, int32_t il) const {
144	        for (int32_t s = head[c]; s >= 0; s = next[s]) {
145	            if (!is_selected(il, key_of[s])) {
146	                return s;
147	            }
148	        }
149	        return -1;
150	    }
151	
152	    int32_t victim(int32_t il) const {
153	        int32_t res = -1;
154	        double res_score = -1.0;
155	        for (int c = 0; c < n_class; ++c) {
156	            const int32_t s = candidate(c, il);
157	            if (s < 0) {
158	                continue;
159	            }
160	            const int32_t key = key_of[s];
161	            if (key < 0) {
162	                return s; // unused slot
163	            }
164	            const int64_t age   = clock[key_layer(key)] - last_use[key];
165	            const double  score = std::ldexp((double) age, -c); // age/2^class
166	            if (score > res_score) {
167	                res       = s;
168	                res_score = score;
169	            }
170	        }
171	        if (res < 0) {
172	            GGML_ABORT("no MoE cache victim");
173	        }
174	        return res;
175	    }
176	
177	    struct fill {
178	        int32_t expert;
179	        int32_t slot;
180	    };
181	
182	    // give a slot to each expert selected by ids (n_tokens tokens) in layer il
183	    // n_cpu(n) of the n misses are left to the CPU and read a zero slot on the device, they are not cached
184	    // a zero slot is used at most once per token, a miss that does not get one is cached instead
185	    // returns false if the ids select more distinct experts than there are slots
186	    template <typename F>
187	    bool plan(int32_t il, const int32_t * ids, size_t n_ids, int64_t n_tokens, int32_t n_used, int32_t n_zero, F && n_cpu,
188	            std::vector<fill> & fills, std::vector<fill> & cpu, size_t & n_hit) {
189	        fills.clear();
190	        cpu.clear();
191	        n_hit = 0;
192	
193	        if (++seen_gen == 0) {
194	            std::fill(seen.begin(), seen.end(), 0);
195	            seen_gen = 1;
196	        }
197	        uniq.clear();
198	        for (size_t i = 0; i < n_ids; ++i) {
199	            GGML_ASSERT(ids[i] >= 0 && ids[i] < n_expert);
200	            if (seen[ids[i]] != seen_gen) {
201	                seen[ids[i]] = seen_gen;
202	                uniq.push_back(ids[i]);
203	            }
204	        }
205	        if (uniq.size() > (size_t) n_slots) {
206	            return false;
207	        }
208	
209	        int32_t * slots = slot_map[il];
210	
211	        // update the CRF of all selected experts and promote hits before choosing victims for misses
212	        misses.clear();
213	        for (int32_t e : uniq) {
214	            const int32_t key = make_key(il, e);
215	            use(il, key);
216	            if (slots[e] < n_slots) {
217	                move(slots[e], class_of(key));
218	                n_hit++;
219	            } else {
220	                misses.push_back(e);
221	            }
222	        }
223	
224	        // the misses with the lowest CRF are left to the CPU, a miss that keeps being used gains CRF and enters the cache
225	        // all misses are used at the same clock, so their CRF compare without decay
226	        const size_t n_c = std::min(n_cpu(misses.size()), misses.size());
227	        if (n_c > 0) {
228	            std::sort(misses.begin(), misses.end(), [&](int32_t a, int32_t b) {
229	                const float crf_a = crf[make_key(il, a)];
230	                const float crf_b = crf[make_key(il, b)];
231	                return crf_a != crf_b ? crf_a < crf_b : a < b;
232	            });
233	            GGML_ASSERT((size_t) n_tokens*n_used == n_ids);
234	            token_zero.assign(n_tokens, 0);
235	            size_t n_keep = n_c;
236	            for (size_t i = 0; i < n_keep; ) {
237	                const int32_t e = misses[i];
238	                uint64_t used = 0;
239	                for (int64_t it = 0; it < n_tokens; ++it) {
240	                    for (int32_t k = 0; k < n_used; ++k) {
241	                        if (ids[it*n_used + k] == e) {
242	                            used |= token_zero[it];
243	                        }
244	                    }
245	                }
246	                int32_t z = 0;
247	                while (z < 64 && (used >> z & 1)) {
248	                    z++;
249	                }
250	                if (z >= n_zero) {
251	                    std::swap(misses[i], misses[--n_keep]);
252	                    continue;
253	                }
254	                for (int64_t it = 0; it < n_tokens; ++it) {
255	                    for (int32_t k = 0; k < n_used; ++k) {
256	                        if (ids[it*n_used + k] == e) {
257	                            token_zero[it] |= 1ull << z;
258	                        }
259	                    }
260	                }
261	                slots[e] = n_slots + z;
262	                cpu.push_back({ e, n_slots + z });
263	                i++;
264	            }
265	            misses.erase(misses.begin(), misses.begin() + n_keep);
266	        }
267	
268	        // fill the misses in expert order: victim() takes unused slots, and slots filled by one plan(), in list order,
269	        // so consecutive experts often get consecutive slots and one upload
270	        std::sort(misses.begin(), misses.end());
271	        for (int32_t e : misses) {
272	            const int32_t s = victim(il);
273	            if (key_of[s] >= 0) {
274	                slot_map[key_layer(key_of[s])][key_expert(key_of[s])] = empty;
275	            } else {
276	                n_filled++;
277	            }
278	            const int32_t key = make_key(il, e);
279	            key_of[s] = key;
280	            slots[e]  = s;
281	            move(s, class_of(key));
282	            fills.push_back({ e, s });
283	        }
284	        clock[il] += n_tokens;
285	        return true;
286	    }
287	};
288	
289	// gate, up, down or gate_up, down
290	static std::vector<ggml_tensor *> llama_moe_cache_layer_experts(const llama_layer & layer) {
291	    std::vector<ggml_tensor *> res;
292	    for (ggml_tensor * t : { layer.ffn_gate_up_exps, layer.ffn_gate_exps, layer.ffn_up_exps, layer.ffn_down_exps }) {
293	        if (t != nullptr) {
294	            res.push_back(t);
295	        }
296	    }
297	    return res;
298	}
299	
300	static bool llama_moe_cache_same_layout(const std::vector<ggml_tensor *> & a, const std::vector<ggml_tensor *> & b) {
301	    if (a.size() != b.size()) {
302	        return false;
303	    }
304	    for (size_t i = 0; i < a.size(); ++i) {
305	        if (a[i]->type != b[i]->type || !ggml_are_same_shape(a[i], b[i]) || a[i]->nb[2] != b[i]->nb[2]) {
306	            return false;
307	        }
308	    }
309	    return true;
310	}
311	
312	static bool llama_moe_cache_is_host_weight(const ggml_tensor * t) {
313	    return t->buffer != nullptr &&
314	        ggml_backend_buffer_get_usage(t->buffer) == GGML_BACKEND_BUFFER_USAGE_WEIGHTS &&
315	        ggml_backend_buffer_is_host(t->buffer);
316	}
