# Checker wrapper: runs the unmodified cc/acc/datasets.py main() with a retrying opener (HTTP 429 backoff only).
import sys, time, urllib.request, urllib.error
sys.path.insert(0, "/home/muk/projects/siminfeng/campaign/cc/acc")
import datasets

def retrying_urlopen(url, timeout=60):
    for attempt in range(12):
        try:
            return urllib.request.urlopen(url, timeout=timeout)
        except urllib.error.HTTPError as exc:
            if exc.code != 429:
                raise
            time.sleep(min(30, 3 + 3 * attempt))
    raise RuntimeError("429 persisted")

_orig = datasets.fetch_rows
datasets.fetch_rows = lambda d, c, s, opener=None: _orig(d, c, s, opener=retrying_urlopen)
