@contextmanager
def exclusive(out):
    out.mkdir(parents=True, exist_ok=True)
    with (out / '.ladder.lock').open('a') as stream:
        try:
            fcntl.flock(stream, fcntl.LOCK_EX | fcntl.LOCK_NB)
